DO $$ BEGIN CREATE TYPE user_role AS ENUM ('ADMIN','SALES','WAREHOUSE','ACCOUNTS'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE customer_type AS ENUM ('RETAIL','WHOLESALE','DISTRIBUTOR'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE customer_status AS ENUM ('LEAD','ACTIVE','INACTIVE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE challan_status AS ENUM ('DRAFT','CONFIRMED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE movement_type AS ENUM ('IN','OUT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role user_role NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id SERIAL PRIMARY KEY, name TEXT NOT NULL, mobile TEXT NOT NULL, email TEXT, business_name TEXT, gst_number TEXT, type customer_type NOT NULL DEFAULT 'RETAIL', address TEXT, status customer_status NOT NULL DEFAULT 'LEAD', follow_up_date DATE, notes TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_followups (id SERIAL PRIMARY KEY, customer_id INTEGER REFERENCES customers(id) ON DELETE CASCADE, note TEXT NOT NULL, follow_up_date DATE, created_by INTEGER REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, name TEXT NOT NULL, sku TEXT UNIQUE NOT NULL, category TEXT NOT NULL, unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price >= 0), current_stock INTEGER NOT NULL DEFAULT 0 CHECK(current_stock >= 0), minimum_stock INTEGER NOT NULL DEFAULT 0, location TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements (id SERIAL PRIMARY KEY, product_id INTEGER REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), type movement_type NOT NULL, reason TEXT NOT NULL, created_by INTEGER REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS challans (id SERIAL PRIMARY KEY, challan_number TEXT UNIQUE NOT NULL, customer_id INTEGER REFERENCES customers(id), status challan_status NOT NULL DEFAULT 'DRAFT', total_quantity INTEGER NOT NULL DEFAULT 0, created_by INTEGER REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS challan_items (id SERIAL PRIMARY KEY, challan_id INTEGER REFERENCES challans(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id), product_name TEXT NOT NULL, sku TEXT NOT NULL, unit_price NUMERIC(12,2) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0));
CREATE INDEX IF NOT EXISTS customers_name_idx ON customers USING gin(to_tsvector('simple', name || ' ' || coalesce(business_name,'')));
